#include <string>

class Solution {
public:
    int numSub(std::string s) {
        const int MOD = 1e9 + 7;
        long long ans = 0, cur = 0;
        for (char ch : s) {
            if (ch == '1') {
                cur++;
                ans = (ans + cur) % MOD;
            } else {
                cur = 0;
            }
        }
        return ans;
    }
};

class Solution {
    public int numSub(String s) {
        final int MOD = 1000000007;
        long ans = 0, cur = 0;
        for (int i = 0; i < s.length(); i++) {
            if (s.charAt(i) == '1') {
                cur++;
                ans = (ans + cur) % MOD;
            } else {
                cur = 0;
            }
        }
        return (int) ans;
    }
}

var numSub = function(s) {
    const MOD = 1000000007n;
    let ans = 0n, cur = 0n;
    for (const ch of s) {
        if (ch === "1") {
            cur++;
            ans = (ans + cur) % MOD;
        } else {
            cur = 0n;
        }
    }
    return Number(ans);
};
